query:
DELETE FROM product_categories
WHERE id IN (
  SELECT id FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY nameAr, parentId ORDER BY id DESC) as rn
    FROM product_categories
    WHERE parentId IS NOT NULL
  ) t
  WHERE rn > 1
);

